// Generated by `just generate` from `src/plugins/claudetto/slices/handoff/lab/command.test.ts`. Edit the source and run `just generate`.
// Lab tests of the manual handoff command `/handoff` (design D3, spec `handoff`, "Manual handoff command").
// The stubs answer the surfaces, the fork, the write, the stat, the timer, the commands, the submit, and the registration.
// The hook of the command writes the file, and a `$.clock.after` timer after the hook clears and submits, or runs `/compact`,
// because Claude Code refuses these calls in a `command.run` hook.

import type { ModelForkResult, On } from "claude-code";
import { type Engine, expect, test } from "claude-code/testing";

const HANDOFF =
  // biome-ignore lint/plugin: test input data
  "- Read `a.txt` lines 1 to 600: DONE, line 1 is `amber-falcon-42`.\n- Next: read lines 601 to 1200.";

const NO_USAGE = {
  input_tokens: 0,
  output_tokens: 0,
  cache_read_input_tokens: 0,
  cache_creation_input_tokens: 0,
};

/** What the stubs answer: the surfaces of the session, the fork, and the size of the file after the write. */
type World = {
  surfaces?: ("terminal" | "desktop")[];
  fork?: ModelForkResult;
  size?: number;
  isTimerRefused?: boolean;
  /** A fork that throws, as an SDK error does. */
  isForkThrowing?: boolean;
};

/** What the hooks did, in order: each write, timer, command, submit, and registration. */
type Seen = string[];

/** The stubs for `world`. */
const engine = (on: On, world: World = {}): Seen => {
  const seen: Seen = [];
  on("session.surfaces", () => ({ value: world.surfaces ?? ["terminal"] }));
  on("model.fork", () => {
    if (world.isForkThrowing) throw new Error("sdk error");
    return {
      value: world.fork ?? {
        isAnswered: true,
        text: HANDOFF,
        usage: NO_USAGE,
      },
    };
  });
  on("fs.write", (_$, e) => {
    seen.push(`write ${e.path.slice(e.path.indexOf(".claudetto/"))}`);
    return { value: undefined };
  });
  on("fs.stat", () => ({
    value: { kind: "file", size: world.size ?? 100, mtimeMs: 0, isLink: false },
  }));
  on("command.run", (_$, e) => {
    seen.push(`command ${e.command}`);
    return { text: "core" };
  });
  on("prompt.submit", (_$, e) => {
    seen.push(`submit ${e.text}`);
    return { text: e.text };
  });
  on("clock.after", (_$, e) => {
    if (world.isTimerRefused) throw new Error("refused");
    seen.push(`timer ${e.ms}`);
    return { value: undefined };
  });
  on("command.register", (_$, e) => {
    seen.push(`register ${e.name}`);
    return { value: { command: e.name } };
  });
  on("session.start", (_$, e) => ({ cwd: e.cwd }));
  on("tool.register", (_$, e) => ({
    value: { tool: `mcp__claudetto__${e.name}` },
  }));
  on("ui.status", (_$, e) => {
    seen.push(`status ${e.text ?? "none"}`);
    return { value: undefined };
  });
  on("ui.log", (_$, e) => {
    seen.push(`log ${e.text}`);
    return { value: undefined };
  });
  return seen;
};

const typed = ($: Engine, command: string) =>
  $.command.run({
    command,
    args: "",
    origin: { kind: "composer" },
    presentation: { isFullscreen: false, columns: 80 },
  });

/** Waits until the timer and the step after the hook are done. */
const settled = () => new Promise((resolve) => setTimeout(resolve, 20));

/** `/handoff`, and then its step. */
const handedOver = async ($: Engine) => {
  const out = await typed($, "handoff");
  await settled();
  return out;
};

// biome-ignore lint/plugin: a test name
test("on a terminal, the command writes the handoff, clears the chat, and submits the handed message", async ($: Engine, on: On) => {
  const seen = engine(on);
  const out = await handedOver($);
  expect(out.text).toBeUndefined();
  expect(seen[0]).toBe("status Writing the handoff…");
  expect(seen[1]).toMatch(
    /^write \.claudetto\/handoff\/handoff-\d{8}T\d{6}Z\.md$/,
  );
  expect(seen[2]).toBe("status none");
  expect(seen[3]).toBe("timer 0");
  expect(seen[4]).toBe("command clear");
  expect(seen[5]).toBe("register handoff");
  expect(seen[6]).toBe("register handoff-setup");
  expect(seen[7]).toBe(`log The handoff is in ${seen[1]?.slice(6)}.`);
  expect(seen[8]).toContain("submit This is the handoff");
  expect(seen[8]).toContain(HANDOFF);
  expect(seen).toHaveLength(9);
});

// biome-ignore lint/plugin: a test name
test("in `-p`, with no surface, the command runs `/compact` in a timer and does not clear", async ($: Engine, on: On) => {
  const seen = engine(on, { surfaces: [] });
  await handedOver($);
  expect(seen).toEqual(["timer 0", "command compact"]);
});

test("a refused timer runs no step and gives no error", async ($: Engine, on: On) => {
  const seen = engine(on, { surfaces: [], isTimerRefused: true });
  await handedOver($);
  expect(seen).toEqual([]);
});

const FALLBACKS: [string, World][] = [
  [
    "a fork with nothing to fork",
    { fork: { isAnswered: false, reason: "nothing-to-fork" } },
  ],
  [
    "a fork text with no value in backticks",
    { fork: { isAnswered: true, text: "No handoff.", usage: NO_USAGE } },
  ],
  ["a fork that throws", { isForkThrowing: true }],
  ["an empty file", { size: 0 }],
  ["a session on the desktop surface only", { surfaces: ["desktop"] }],
];

for (const [name, world] of FALLBACKS) {
  // biome-ignore lint/plugin: a test name
  test(`on a terminal, ${name} gives the compaction path, with no clear and no submit`, async ($: Engine, on: On) => {
    const seen = engine(on, world);
    await handedOver($);
    expect(seen.slice(-2)).toEqual(["timer 0", "command compact"]);
    expect(seen.filter((s) => /^(submit|register|log)/.test(s))).toEqual([]);
  });
}

test("another command runs unchanged", async ($: Engine, on: On) => {
  const seen = engine(on);
  const out = await typed($, "usage");
  expect(out.text).toBe("core");
  expect(seen).toEqual(["command usage"]);
});

test("the session start registers the command `handoff`", async ($: Engine, on: On) => {
  const seen = engine(on);
  await $.session.start({ cwd: "/p", surface: null, isInteractive: false });
  expect(seen).toEqual(["register handoff", "register handoff-setup"]);
});

test("a refused name gives no error at session start", async ($: Engine, on: On) => {
  on("session.start", (_$, e) => ({ cwd: e.cwd }));
  on("tool.register", (_$, e) => ({
    value: { tool: `mcp__claudetto__${e.name}` },
  }));
  on("command.register", () => {
    throw new Error(
      '"/handoff" refused: the plugin other registered it already',
    );
  });
  await $.session.start({ cwd: "/p", surface: null, isInteractive: false });
});
